n = int(input())
arr = list(map(int, input().split()))
lines = []
for i in range(n - 1):
    for j in range(n - 1 - i):
        if arr[j] > arr[j + 1]:
            arr[j], arr[j + 1] = arr[j + 1], arr[j]
    lines.append(' '.join(map(str, arr)))
print('\n'.join(lines))

