s = input()
pairs = {')': '(', ']': '[', '}': '{'}
stack = []
valid = True
for ch in s:
    if ch in '([{':
        stack.append(ch)
    elif ch in ')]}':
        if not stack or stack.pop() != pairs[ch]:
            valid = False
            break
if stack:
    valid = False
print("Valid" if valid else "Invalid")

