import sys
sys.setrecursionlimit(10000)
memo = {0: 0, 1: 1}
def fib(k):
    if k in memo:
        return memo[k]
    memo[k] = fib(k - 1) + fib(k - 2)
    return memo[k]
n = int(input())
print(fib(n))

