mat = [list(map(int, input().split())) for _ in range(r)]
found = False
for i in range(r):
    row_max = max(mat[i])
    for j in range(c):
        if mat[i][j] == row_max:
            col_min = min(mat[k][j] for k in range(r))
            if mat[i][j] == col_min:
                print(mat[i][j], i + 1, j + 1)
                found = True
                break
    if found:
        break
if not found:
    print("None")

