import sys
sys.setrecursionlimit(10000)
memo = {}
def comb(n, k):
    if k == 0 or k == n:
        return 1
    if (n, k) in memo:
        return memo[(n, k)]
    res = comb(n - 1, k - 1) + comb(n - 1, k)
    memo[(n, k)] = res
    return res
n, k = map(int, input().split())
print(comb(n, k))

